#!/usr/bin/env python3
from pathlib import Path
import base64
import hashlib
import shutil

ROOT = Path.cwd()
MIDI_DIR = ROOT / "sound/songs/midi"
DST = MIDI_DIR / "mus_meet_me_halfway.mid"

DATA = """"""
EXPECTED_SHA256 = "1aa37f26413c441caf9efa4206dac05470aef8e7fd0c2b48f41b4560a41f2102"

if not (ROOT / "include/constants/songs.h").exists() or not MIDI_DIR.exists():
    raise SystemExit("ERRO: rode este Python na raiz do pokeemerald-expansion.")

if DST.exists():
    backup = DST.with_name(DST.name + ".before_drum_fix_v4")
    if not backup.exists():
        shutil.copyfile(DST, backup)
        backup.touch()
        print("[BACKUP]", backup)

data = base64.b64decode(DATA)
if hashlib.sha256(data).hexdigest() != EXPECTED_SHA256:
    raise SystemExit("ERRO INTERNO: hash do MIDI V4 invalido.")

DST.write_bytes(data)
DST.touch()
print("[WRITE]", DST)

asm = MIDI_DIR / "mus_meet_me_halfway.s"
if asm.exists():
    asm.unlink()
    print("[DELETE]", asm)

for obj in ROOT.glob("build/*/sound/songs/midi/mus_meet_me_halfway.o"):
    obj.unlink()
    print("[DELETE]", obj)

print()
print("[OK] Meet Me Halfway - DRUM FIX V4 instalado")
print("Bateria simplificada: kick + snare/clap + closed hi-hat suave")
print("Splash/crash/ride/pedal hi-hat e percussao ornamental removidos")
print("Melodia, baixo, estrutura e Radio preservados")
print()
print("Agora rode:")
print("  make -j9")
